// AccountInstrumentOwnershipExists calls AccountInstrumentOwnershipExistsFunc.
func (mock *RepositoryMock) AccountInstrumentOwnershipExists(ctx context.Context, accountInstrumentOwnershipID string, accountID string) (bool, error) {
	if mock.AccountInstrumentOwnershipExistsFunc == nil {
		panic("RepositoryMock.AccountInstrumentOwnershipExistsFunc: method is nil but Repository.AccountInstrumentOwnershipExists was just called")
	}
	callInfo := struct {
		Ctx                          context.Context
		AccountInstrumentOwnershipID string
		AccountID                    string
	}{
		Ctx:                          ctx,
		AccountInstrumentOwnershipID: accountInstrumentOwnershipID,
		AccountID:                    accountID,
	}
	mock.lockAccountInstrumentOwnershipExists.Lock()
	mock.calls.AccountInstrumentOwnershipExists = append(mock.calls.AccountInstrumentOwnershipExists, callInfo)
	mock.lockAccountInstrumentOwnershipExists.Unlock()
	return mock.AccountInstrumentOwnershipExistsFunc(ctx, accountInstrumentOwnershipID, accountID)
}

